-- Venue Live Guest "Golden Anniversary 50 Tahun". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara goldenanniv), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'goldenanniv', 'Golden Anniversary 50 Tahun', 'goldenanniv', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 149, 'center 38%',
  $t${"name":"Golden Anniversary","orn":"diamond","ui":{"ivory":"#FBF5E8","white":"#FFFFFF","soft":"#EEDFC2","soft2":"#C9A24A","accent":"#B5882E","deep":"#4A3320","ink":"#4A3320","mute":"#8D7A5A","line":"#E8D8B8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F7EEDA","ink":"#4A3320","accent":"#B5882E","gold":"#C9A24A","leaf":"#EEDFC2","hbg":"rgba(251,245,232,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(74,51,32,.9)","acc":"#F2C94C","on":"#4A3320"},"scr":{"wine":"#4A3320","veil":"251,245,232"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'goldenanniv');
