:"Kak Kebaya Emas"},"av_p2":{"url":"/assets/live-decor/goldenanniv/av_p2.webp","name":"Kak Hijab Krem"},"av_p3":{"url":"/assets/live-decor/goldenanniv/av_p3.webp","name":"Kak Topi Bunga"}}$d$::jsonb, background_url = '/assets/live-decor/goldenanniv/painting.webp', active = true, updated_at = now() where key = 'goldenanniv';
